import {ACTION_LABELS} from './data.js';
import {keyName} from './input.js';
export function renderSettings(game){
 const s=game.settings;
 const slider=(k,n,min,max,step)=>`<label class="setting">${n}<input type="range" min="${min}" max="${max}" step="${step}" value="${s[k]}" data-setting="${k}" aria-label="${n}"></label>`;
 const toggle=(k,n)=>`<label class="setting">${n}<input type="checkbox" ${s[k]?'checked':''} data-setting="${k}"></label>`;
 return `<div class="eyebrow">Make the expedition yours</div><h3>Settings & accessibility</h3><div class="settings-grid">${slider('master','Master volume',0,1,.05)}${slider('music','Music',0,1,.05)}${slider('sfx','Effects',0,1,.05)}${slider('ambient','Wind & ambience',0,1,.05)}${toggle('muteUnfocused','Mute when unfocused')}${toggle('subtitles','Essential sound captions')}${slider('sensitivity','Mouse sensitivity',.2,2.5,.1)}${slider('gamepadSensitivity','Gamepad sensitivity',.2,2.5,.1)}${slider('textScale','Text size',.85,1.35,.05)}${toggle('invertY','Invert camera Y')}${toggle('reducedMotion','Reduced motion')}${toggle('highContrast','High contrast HUD')}${toggle('climbAssist','Mineral climbing assistance')}${toggle('sprintToggle','Toggle sprint')}${toggle('showCompass','Compass')}${toggle('showMinimap','Minimap')}${toggle('guidance','Objective guidance')}<label class="setting">Graphics preset<select data-setting="quality"><option value="high" ${s.quality==='high'?'selected':''}>High</option><option value="low" ${s.quality==='low'?'selected':''}>Performance</option></select></label>${slider('resolution','Resolution cap',.65,1.5,.05)}${slider('vegetation','Grass density',.3,1,.05)}${slider('shadowDistance','Shadow distance',24,70,2)}</div><p style="font-size:.68rem;margin-top:14px">Performance disables dynamic shadows and lowers resolution and grass density. Individual sliders change the actual renderer; no unsupported effects are advertised.</p><div class="journal-rule"></div><div class="eyebrow">Remap controls · select a key, then press a replacement</div><div class="control-grid">${Object.entries(ACTION_LABELS).map(([a,n])=>`<div class="control"><span>${n}</span><button data-action="rebind" data-value="${a}">${keyName(s.bindings[a])}</button></div>`).join('')}</div><div class="button-row"><button class="secondary" data-action="resetControls">Reset controls</button></div><p style="font-size:.68rem;margin-top:14px">A binding conflict swaps the two keys. Controller prompts switch automatically; physical gamepad verification is still pending.</p>`;
}
